def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    cnt=Counter(x for row in grid for x in row)
    def runs(line,col):
        ret=[]; i=0
        while i<len(line):
            if line[i]!=col: i+=1; continue
            j=i
            while j+1<len(line) and line[j+1]==col: j+=1
            ret.append((i,j)); i=j+1
        return ret
    candidates=[]
    for wall in cnt:
        if wall==bg: continue
        for a in runs(grid[0],wall):
            for b in runs(grid[-1],wall):
                if a[1]-a[0]==b[1]-b[0]: candidates.append(('h',wall,a,b))
        for a in runs([row[0] for row in grid],wall):
            for b in runs([row[-1] for row in grid],wall):
                if a[1]-a[0]==b[1]-b[0]: candidates.append(('v',wall,a,b))
    if not candidates: return [row[:] for row in grid]
    def source_positions(wall):
        return [(r,c) for r in range(h) for c in range(w) if grid[r][c]!=bg and grid[r][c]!=wall]
    def score(item):
        ori,wall,a,b=item; src=source_positions(wall)
        inds=[c if ori=='h' else r for r,c in src]
        return (sum(a[0]<=i<=a[1] for i in inds)+sum(b[0]<=i<=b[1] for i in inds), (a[1]-a[0]+1)+(b[1]-b[0]+1))
    ori,wall,a,b=max(candidates,key=score)
    src=source_positions(wall)
    if not src: return [row[:] for row in grid]
    seed=Counter(grid[r][c] for r,c in src).most_common(1)[0][0]
    out=[row[:] for row in grid]
    for r,c in src:
        ix=c if ori=='h' else r
        first=a[0]<=ix<=a[1]; second=b[0]<=ix<=b[1]
        # Source lies by one of the two apertures; shoot toward that edge.
        toward_first=first if first!=second else True
        own,opp=(a,b) if toward_first else (b,a)
        mapped=opp[0]+(ix-own[0])
        if ori=='h':
            if toward_first:
                for rr in range(r-1,0,-1):
                    if out[rr][c]==bg: out[rr][c]=seed
                for rr in range(h-2,-1,-1):
                    if out[rr][mapped]==bg: out[rr][mapped]=seed
            else:
                for rr in range(r+1,h-1):
                    if out[rr][c]==bg: out[rr][c]=seed
                for rr in range(1,h):
                    if out[rr][mapped]==bg: out[rr][mapped]=seed
        else:
            if toward_first: # left edge
                for cc in range(c-1,0,-1):
                    if out[r][cc]==bg: out[r][cc]=seed
                for cc in range(w-2,-1,-1):
                    if out[mapped][cc]==bg: out[mapped][cc]=seed
            else: # right edge
                for cc in range(c+1,w-1):
                    if out[r][cc]==bg: out[r][cc]=seed
                for cc in range(1,w):
                    if out[mapped][cc]==bg: out[mapped][cc]=seed
        out[r][c]=4
    return out
